{
  "name": "harness",
  "version": "0.1.0",
  "description": "Shows and drives Herdr-Jev role plans inside Claude Code: the advisor is the session, and the implementer, reviewer and reader models come from herdr-jev models list.",
  "types": "./types/index.d.ts",
  "userConfig": {
    "herdrJevBin": {
      "type": "string",
      "title": "herdr-jev binary",
      "description": "Executable used for triage, plan and review. Resolved through PATH unless absolute.",
      "default": "herdr-jev"
    },
    "maxWorkers": {
      "type": "number",
      "title": "Max parallel workers",
      "description": "Most implementer and reader tasks harness_run starts at once.",
      "default": 3
    },
    "autoRun": {
      "type": "boolean",
      "title": "Run tasks automatically",
      "description": "harness_plan starts every ready task and each finished task starts the next ready ones.",
      "default": true
    },
    "scopeMode": {
      "type": "string",
      "title": "Scope mode",
      "description": "off, report or enforce. enforce hides skills and agents the harness did not select for the task; report only computes the receipt.",
      "default": "enforce"
    },
    "runbook": {
      "type": "string",
      "title": "Scope runbook",
      "description": "Optional ai-harness runbook id passed to skill-select --runbook.",
      "default": ""
    },
    "alwaysAllowSkills": {
      "type": "string",
      "title": "Always visible skills",
      "description": "Comma separated skill names the scope never hides.",
      "default": "writing-clearly-and-concisely,harness-router,herdr-jev,ai-harness-context,plugin-authoring,vault,promote,code-review,simplify"
    },
    "alwaysAllowAgents": {
      "type": "string",
      "title": "Always offered agents",
      "description": "Comma separated agent names the scope never hides, besides built-ins, harness:* and the project's own agents.",
      "default": "business-operator,claudex-coordinator,commercial-operator,harness-operator,knowledge-maintainer,legacy-archaeologist,media-producer,platform-reliability,product-discovery,quality-reviewer,recording-analyst,research-analyst,security-operator,software-architect,software-engineer,web-experience"
    },
    "autoReview": {
      "type": "boolean",
      "title": "Refresh the harness review automatically",
      "description": "Run the herdr-jev review once when every task is done or approved and at least one is approved.",
      "default": false
    },
    "prGateAsk": {
      "type": "boolean",
      "title": "Ask before opening a PR without a ready review",
      "description": "Off by default: the PR command always runs and the model is told the review status. On: the engine asks the person to confirm when the status is known and not ready.",
      "default": false
    },
    "codex": {
